func startRunCore(ctx context.Context, b *nsbundle.Bundle, log *xlog.Logger,
	runIdRaw, pipelineName string, params []byte, image string, labels map[string]string, trigger, owner string,
) (startOutcome, error) {
	runId, err := id.ParseRunId(runIdRaw)
	if err != nil {
		return startOutcome{}, status.Error(codes.InvalidArgument, err.Error())
	}
	if pipelineName == "" {
		return startOutcome{}, status.Error(codes.InvalidArgument, "pipeline is required")
	}
	if err := wire.ValidateUserLabels(labels); err != nil {
		return startOutcome{}, status.Error(codes.InvalidArgument, err.Error())
	}
	params, err = normalizeAndValidate(ctx, b, pipelineName, params)
	if err != nil {
		return startOutcome{}, err
	}
	opts := client.StartWorkflowOptions{
		ID:        "run/" + string(runId),
		TaskQueue: wire.RunQueue(runId),
		// A run id names ONE logical execution, in EVERY state. A start
		// under a taken id — open or closed, however it closed — fails
		// here and is answered by replayStart: the same request is that
		// run, another request is a conflict. Re-starting a failed run
		// under its own id was allowed once; it forked a second execution
		// under one name whenever a caller retried after a lost answer,
		// and one record then stood for two executions' results, events
		// and resources. A re-run is a new id.
		WorkflowIDConflictPolicy: enums.WORKFLOW_ID_CONFLICT_POLICY_FAIL,
		WorkflowIDReusePolicy:    enums.WORKFLOW_ID_REUSE_POLICY_REJECT_DUPLICATE,
		// The request's identity rides with the execution, so a replay
		// is told from a conflict for as long as the execution is
		// remembered — the namespace's retention is the horizon of this
		// promise, and after it a run id is a new name.
		Memo: map[string]any{pipelineflow.MemoRequest: pipelineflow.RequestDigest(pipelineName, params)},
	}
	// The run carries its labels in the same EntityLabels attribute
	// resources use — one label language across the system. The system
	// markers go on after the user's labels are validated: the tree
	// says a run belongs to a pipeline, and these say WHICH version of
	// the code it executes and WHAT started it.
	marked := make(map[string]string, len(labels)+5)
	for k, v := range labels {
		marked[k] = v
	}
	marks := map[string]string{
		syslabels.Pipeline: pipelineName,
		syslabels.Trigger:  trigger,
		syslabels.Image:    image,
	}
	// The revision (and through it the source) is what a person means
	// by "which code ran" — it is not an edge of any tree.
	if st, err := b.Worker.GetPipeline(ctx, pipelineName); err == nil {
		marks[syslabels.Revision] = st.RevisionId
		if st.RevisionId != "" {
			if _, rspec, _, rerr := b.Worker.DescribeRevision(ctx, pipelineName, st.RevisionId); rerr == nil {
				marks[syslabels.Source] = rspec.SourceRef
				marks[syslabels.SourceDigest] = shortDigest(rspec.SourceDigest)
			}
		}
	}
	marked = syslabels.Merge(marked, marks)
	opts.TypedSearchAttributes = runAttributes(pipelineName, owner, marked)
	var args []any
	if len(params) > 0 {
		args = append(args, json.RawMessage(params))
	}
	run, err := b.Client.ExecuteWorkflow(ctx, opts, pipelineName, args...)
	if err != nil {
		var taken *serviceerror.WorkflowExecutionAlreadyStarted
		if errors.As(err, &taken) {
			return replayStart(ctx, b, log, runId, pipelineName, params, image)
		}
		return startOutcome{}, temporalStatus(err, codes.Unavailable)
	}
	if image != "" {
		if err := b.Runner.Start(ctx, runId, image, mintRunToken(b, runId)); err != nil {
			return startOutcome{}, status.Error(codes.Internal, err.Error())
		}
	}
	rctx := obs.WithEntity(ctx, "run/"+string(runId))
	obs.Info(rctx, "run started",
		obs.Str("pipeline", pipelineName), obs.Str("trigger", trigger),
		obs.Str("revision", marks[syslabels.Revision]))
	obs.Count(rctx, MetricRunStarted, 1,
		obs.Str("pipeline", pipelineName), obs.Str("trigger", trigger))
	log.Info("run started",
		xlog.String("namespace", b.Namespace),
		xlog.Any("run", runId),
		xlog.String("pipeline", pipelineName),
		xlog.Bool("managed", image != ""))
	return startOutcome{WorkflowId: run.GetID(), TemporalRunId: run.GetRunID(), RunId: string(runId), Decision: pipelineflow.DecisionStarted}, nil
}

// replayStart answers a start whose id is already taken. The same
// request — pipeline and params — IS that run, in whatever state it is,
// and is returned as it is: nothing begins twice under one name; while
// it is open its managed executor is ensured, so a start whose container
// failed can be asked again. Another request under the id is a conflict,
// never a second execution.

fire_run.source:
func fireRun(ctx context.Context, b *nsbundle.Bundle, pipelineId, runId string, params []byte, labels map[string]string) (pipelineflow.FireRes, error) {
	if pipelineId == "" {
		return pipelineflow.FireRes{}, status.Error(codes.InvalidArgument, "pipeline is required")
	}
	if err := wire.ValidateUserLabels(labels); err != nil {
		return pipelineflow.FireRes{}, status.Error(codes.InvalidArgument, err.Error())
	}
	// Validate at the DOOR, before the firing enters the arbiter — a bad
	// submit fails the caller synchronously here, instead of surfacing later
	// through the retryable start activity the arbiter drives.
	params, err := normalizeAndValidate(ctx, b, pipelineId, params)
	if err != nil {
		return pipelineflow.FireRes{}, err
	}
	res, err := b.Worker.FirePipeline(ctx, pipelineId, pipelineflow.FireCmd{
		Params: params, RunId: runId, Labels: labels,
	})
	if err != nil {
		// A refusal of the arbiter is the caller's precondition; a
		// transport that never answered is not — the firing may have
		// been accepted, and the caller must be told to ask again, not
		// that it was refused.
		return pipelineflow.FireRes{}, temporalStatus(err, codes.FailedPrecondition)
	}
	if res.Decision == pipelineflow.DecisionConflict {
		return pipelineflow.FireRes{}, status.Errorf(codes.AlreadyExists,
			"run %s already names another request of pipeline %s: a re-run needs a new run id", res.RunId, pipelineId)
	}
	// Queued is an answer, not a refusal: the firing has its id and its
	// place, and the caller can ask about it.
	return res, nil
}

// startOutcome is what a start answered: the execution, and whether this
// call began it or found it — the same request, replayed after a lost
// answer, is the same run.
type startOutcome struct {
	WorkflowId, TemporalRunId, RunId string
	// Decision is pipelineflow.DecisionStarted or DecisionExists.
	Decision string
}

// normalizeAndValidate substitutes ${var:...}, checks the params against the
// pipeline's published manifest, and verifies secret refs — all at the DOOR,
// synchronously, so a bad submit fails the caller at once. Both start paths
// use it: the direct managed start (startRunCore) and the arbiter firing
// (fireRun), so a firing never carries params that would only fail later in
// the retryable start activity. No manifest (never pushed) — no gate.

arbiter.source:
func New(tick time.Duration) *entdefine.Definition[Spec, State] {
	def := entdefine.New[Spec, State](Kind,
		entdefine.WithSearchAttributes[Spec, State](true),
		entdefine.WithInit[Spec, State](func(ctx workflow.Context, _ Spec) (State, error) {
			var st State
			// A pipeline is a ROOT: it owns its sources, revisions,
			// triggers, stand and runs; nothing owns it.
			ownership.Init(ctx, &st.State, "")
			return st, nil
		}),
		entdefine.WithReconcileEvery[Spec, State](tick, pendingTick),
		// The pipeline's own bytes are the upload area its sources
		// started from; everything else belongs to a record under it
		// and is swept by that record's own deletion.
		entdefine.WithFinalize[Spec, State](func(ctx workflow.Context, _ *State) error {
			sctx := workflow.WithActivityOptions(ctx, workflow.ActivityOptions{
				TaskQueue:           wire.ServerQueue,
				StartToCloseTimeout: 5 * time.Minute,
				RetryPolicy:         &temporal.RetryPolicy{MaximumAttempts: 5},
			})
			return workflow.ExecuteActivity(sctx, SweepActivity,
				SweepReq{Prefix: "uploads/" + pipelineId(ctx) + "/"}).Get(ctx, nil)
		}),
	)
	ownership.Register(def, func(st *State) *ownership.State { return &st.State })
	entdefine.Handle(def, func(ctx workflow.Context, ec *entdefine.Ctx[Spec, State], cmd ActivateCmd) (PublishRes, error) {
		// The command names a revision, nothing more: the manifest lives
		// in the blob store, and carrying it here would bury this
		// record's history under every activation.
		var rev Activation
		if err := workflow.ExecuteActivity(actx(ctx), ResolveActivity,
			ResolveReq{PipelineId: pipelineId(ctx), RevisionId: cmd.RevisionId}).Get(ctx, &rev); err != nil {
			return PublishRes{}, err
		}
		sum := sha256.Sum256(rev.Manifest)
		digest := "sha256:" + hex.EncodeToString(sum[:])
		st := ec.State()
		changed := st.Digest != digest || st.Image != rev.Image || st.Concurrency != rev.Concurrency
		st.Manifest, st.Digest, st.Image, st.Concurrency = rev.Manifest, digest, rev.Image, rev.Concurrency
		st.RevisionId = cmd.RevisionId
		// Triggers follow the manifest that is now active.
		if err := workflow.ExecuteActivity(actx(ctx), ReconcileTriggersActivity,
			ReconcileReq{PipelineId: pipelineId(ctx), Manifest: rev.Manifest}).Get(ctx, nil); err != nil {
			return PublishRes{}, err
		}
		return PublishRes{Digest: digest, Changed: changed}, nil
	})
	entdefine.Handle(def, func(_ workflow.Context, ec *entdefine.Ctx[Spec, State], cmd PublishCmd) (PublishRes, error) {
		sum := sha256.Sum256(cmd.Manifest)
		digest := "sha256:" + hex.EncodeToString(sum[:])
		st := ec.State()
		same := st.Digest == digest &&
			(cmd.Image == "" || cmd.Image == st.Image) &&
			cmd.Concurrency == st.Concurrency
		if same {
			return PublishRes{Digest: digest, Changed: false}, nil
		}
		if cmd.Image != "" {
			st.Image = cmd.Image
		}
		st.Concurrency = cmd.Concurrency
		st.Manifest = cmd.Manifest
		st.Digest = digest
		return PublishRes{Digest: digest, Changed: true}, nil
	})
	entdefine.Handle(def, func(ctx workflow.Context, ec *entdefine.Ctx[Spec, State], cmd FireCmd) (FireRes, error) {
		st := ec.State()
		fire := Fire(cmd)
		if fire.RunId == "" {
			fire.RunId = nextRunId(ctx, st, fire.Trigger)
		} else {
			// A named firing may be a REPLAY — the caller's answer was
			// lost and it asks again. The one waiting in the slot is
			// still queued; an execution that exists is that run, if it
			// is the same request, and a conflict if it is not. Nothing
			// begins twice under one name.
			if st.Pending != nil && st.Pending.RunId == fire.RunId {
				return FireRes{Decision: DecisionQueued, RunId: fire.RunId}, nil
			}
			var known LookupRes
			if err := workflow.ExecuteActivity(actx(ctx), LookupActivity,
				LookupReq{RunId: fire.RunId, PipelineId: pipelineId(ctx), Params: fire.Params}).Get(ctx, &known); err != nil {
				return FireRes{}, err
			}
			switch {
			case known.Exists && known.Same:
				return FireRes{Decision: DecisionExists, RunId: fire.RunId}, nil
			case known.Exists:
				return FireRes{Decision: DecisionConflict, RunId: fire.RunId}, nil
			}
		}
		running, err := countRuns(ctx, ec)
		if err != nil {
			return FireRes{}, err
		}
		policy := st.Concurrency
		if policy == "" {
			policy = "queue"
		}
		switch {
		case running == 0 || policy == "parallel":
			runId, err := start(ctx, ec, fire)
			if err != nil {
				return FireRes{}, err
			}
			return FireRes{Decision: DecisionStarted, RunId: runId}, nil
		case policy == "cancel-previous":
			if err := workflow.ExecuteActivity(actx(ctx), CancelActivity, pipelineId(ctx)).Get(ctx, nil); err != nil {
				return FireRes{}, err
			}
			runId, err := start(ctx, ec, fire)
			if err != nil {
				return FireRes{}, err
			}
			return FireRes{Decision: DecisionReplaced, RunId: runId}, nil
		default:
			// queue: ONE slot. The newer firing takes it — cron firings do
			// not pile up behind a long run — and the one it pushed out is
			// named in the answer, so nothing is replaced in silence. A
			// displaced id never becomes a run.
			res := FireRes{Decision: DecisionQueued, RunId: fire.RunId}
			if st.Pending != nil {
				res.Displaced = st.Pending.RunId
			}
			st.Pending = &fire
			return res, nil
		}
	})
	return def
}

// nextRunId names a firing nobody named: the pipeline, what fired it,
// when — and a counter when a second firing lands in the same second, so
// two firings never share one name. Named at ACCEPT time: a queued firing
// has its identity before it runs.
